class Solution {
    public int hammingWeight(int n) {
        int count = 0;
        while (n != 0) {
            n &= (n - 1);
            count++;
        }
        return count;
    }
}

class Solution {
    public int hammingWeight(int n) {
        int count = 0;
        for (int i = 0; i < 32; i++) {
            count += n & 1;
            n >>>= 1;
        }
        return count;
    }
}

class Solution {
    public int hammingWeight(int n) {
        int count = 0;
        int mask = 1;
        for (int i = 0; i < 32; i++) {
            if ((n & mask) != 0) {
                count++;
            }
            mask <<= 1;
        }
        return count;
    }
}

class Solution {
    private static final int[] BYTE_COUNTS = buildTable();

    public int hammingWeight(int n) {
        return BYTE_COUNTS[n & 0xff]
             + BYTE_COUNTS[(n >>> 8) & 0xff]
             + BYTE_COUNTS[(n >>> 16) & 0xff]
             + BYTE_COUNTS[(n >>> 24) & 0xff];
    }

    private static int[] buildTable() {
        int[] counts = new int[256];
        for (int i = 1; i < counts.length; i++) {
            counts[i] = counts[i >> 1] + (i & 1);
        }
        return counts;
    }
}

class Solution {
    public int hammingWeight(int n) {
        n = n - ((n >>> 1) & 0x55555555);
        n = (n & 0x33333333) + ((n >>> 2) & 0x33333333);
        n = (n + (n >>> 4)) & 0x0f0f0f0f;
        n = n + (n >>> 8);
        n = n + (n >>> 16);
        return n & 0x3f;
    }
}
